write_plot<-function(mid,p,stem,data,qc,width,height){w<-file.path(W,mid);saveRDS(p,file.path(w,'plot.rds'));write.csv(data,file.path(P,'results/plot_data',paste0(stem,'.csv')),row.names=FALSE);qc$stem<-stem;qc$width_mm<-width;qc$height_mm<-height;wr(qc,file.path(w,'input-qc.json'));ggsave(file.path(w,'exploratory.png'),p,width=width,height=height,units='mm',dpi=180,bg='white',device=ragg::agg_png)}
th<-theme_void(base_size=7,base_family='Arial')+theme(legend.title=element_text(size=7),legend.text=element_text(size=7),legend.key.height=grid::unit(2.8,'mm'),legend.key.width=grid::unit(2.8,'mm'),legend.spacing.y=grid::unit(0,'mm'),legend.margin=margin(1,1,1,1),plot.margin=margin(2,2,2,2))
world<-ggplot2::map_data('world');data(world.cities,package='maps')
# Actual named-city geographic anchors. Synthetic values never represent observations.
names088<-c('Vancouver','New York','Mexico City','San Jose','Bogota','Lima','Sao Paulo','Buenos Aires','Santiago','Caracas','Havana','London','Paris','Madrid','Lisbon','Rome','Berlin','Amsterdam','Oslo','Stockholm','Helsinki','Warsaw','Athens','Moscow','Istanbul','Cairo','Rabat','Lagos','Accra','Nairobi','Cape Town','Addis Abeba','Johannesburg','Tehran','Baghdad','Riyadh','Karachi','Delhi','Mumbai','Dhaka','Kathmandu','Beijing','Shanghai','Guangzhou','Tokyo','Seoul','Bangkok','Hanoi','Singapore','Jakarta','Manila','Taipei','Ulaanbaatar','Tashkent','Sydney','Perth','Auckland','Port Moresby')
select_cities<-function(nms){z<-world.cities[match(tolower(nms),tolower(world.cities$name)),];z$requested<-nms;z<-z[!is.na(z$long),];z[,c('requested','country.etc','long','lat')]}
z<-select_cities(names088);colnames(z)<-c('City','Country','Longitude','Latitude');n<-nrow(z)
groups<-c('hpAfrica1','hpAfrica2','hpAsia2','hpEurope','hpNEAfrica','hpNorthAsia','hpSahul','hspEAsia','hspIndigenousNAmerica','hspIndigenousSAmerica','hspSiberia','hspUral')
# User-authorized structure fixture: sparse, region-associated composition is illustrative only.
z$Size<-sample(c(4,8,15,25,40,70,120,250,500),n,TRUE);counts<-matrix(0,n,12,dimnames=list(NULL,groups))
for(i in seq_len(n)){main<-if(z$Longitude[i]< -30)sample(c(1,4,9,10),1)else if(z$Latitude[i]< -10&&z$Longitude[i]>90)sample(c(7,8),1)else if(z$Longitude[i]>70)sample(c(3,6,8,11),1)else if(z$Latitude[i]<25)sample(c(1,2,5),1)else sample(c(4,6,12),1);ks<-unique(c(main,sample(12,sample(0:2,1))));counts[i,ks]<-as.vector(rmultinom(1,z$Size[i],prob=c(5,rep(1,length(ks)-1))))}
z<-cbind(z,counts);z$radius_deg<-2*log10(z$Size+1);stopifnot(all(rowSums(counts)==z$Size))
# A built-in 12-category set; category order remains the original source order.
pal12<-RColorBrewer::brewer.pal(12,'Paired');names(pal12)<-groups
p<-ggplot()+geom_polygon(data=world,aes(long,lat,group=group),fill='tan',colour='white',linewidth=.13)+geom_scatterpie(data=z,aes(Longitude,Latitude,r=radius_deg),cols=groups,colour='#20272D',linewidth=.16)+scale_fill_manual(values=pal12,name=NULL,breaks=groups)+geom_scatterpie_legend(r=2*log10(c(10,100,500)+1),x=-150,y=-28,n=3,breaks=2*log10(c(10,100,500)+1),labeller=function(r)round(10^(r/2)-1),size=2.3,family='Arial')+coord_quickmap(xlim=c(-180,180),ylim=c(-55,83),expand=FALSE)+th+theme(legend.position='bottom',legend.key.spacing.x=grid::unit(4,'mm'))+guides(fill=guide_legend(nrow=3,byrow=FALSE))
