names089<-c('Vancouver','New York','Mexico City','San Jose','Havana','Bogota','Caracas','Lima','Sao Paulo','Buenos Aires','Santiago','London','Paris','Madrid','Rome','Berlin','Oslo','Moscow','Cape Town','Nairobi','Antananarivo','Port Louis','Tokyo','Seoul','Taipei','Singapore','Jakarta','Manila','Sydney','Melbourne','Perth','Brisbane','Darwin','Auckland','Wellington','Suva','Honolulu','Apia','Nuku Alofa','Papeete')
