# Source-image traced ecological background. Not a substitute for the original ecological shapefile.
china<-st_make_valid(st_read(file.path(D,'china-provinces.geojson'),quiet=TRUE));china<-st_transform(china,4326);aeqd<-'+proj=aeqd +lat_0=35 +lon_0=105 +datum=WGS84 +units=km +no_defs';projected<-st_make_valid(st_transform(china,aeqd))
rdata<-read.csv(file.path(P,'results/plot_data/china_source_traced_zones_20261029.csv'));r<-terra::rast(rdata,type='xyz',crs=aeqd);r<-terra::mask(r,terra::vect(st_union(projected)));veg<-st_as_sf(terra::as.polygons(r,dissolve=TRUE,na.rm=TRUE));names(veg)[1]<-'zone';zones<-c('Alpine vegetation','Boreal coniferous forest','Subtropical evergreen broad-leaved forest','Temperate desert','Temperate grassland','Temperate mixed coniferous–broadleaf forest','Tropical rainforest','Warm temperate deciduous broad-leaved forest');veg$region_en<-factor(zones[veg$zone],levels=zones)
st_write(veg,file.path(P,'results/plot_data/china_source_traced_zones_20261029.geojson'),delete_dsn=TRUE,quiet=TRUE)
eng<-c('Beijing','Tianjin','Hebei','Shanxi','Inner Mongolia','Liaoning','Jilin','Heilongjiang','Shanghai','Jiangsu','Zhejiang','Anhui','Fujian','Jiangxi','Shandong','Henan','Hubei','Hunan','Guangdong','Guangxi','Hainan','Chongqing','Sichuan','Guizhou','Yunnan','Tibet','Shaanxi','Gansu','Qinghai','Ningxia','Xinjiang','Taiwan','Hong Kong','Macao','');china$Province<-eng;projected$Province<-eng
cp<-subset(world.cities,country.etc=='China'&pop>100000);pts<-st_transform(st_as_sf(cp,coords=c('long','lat'),crs=4326,remove=FALSE),aeqd);keep<-lengths(st_intersects(pts,projected))>0;cp<-cp[keep,];pts<-pts[keep,];pick<-sample(seq_len(nrow(cp)),160);cp<-cp[pick,];pts<-pts[pick,];xy<-st_coordinates(pts);cp$X<-xy[,1];cp$Y<-xy[,2];genres<-c('Rhipicephalus','Dermacentor','Amblyomma','Haemaphysalis','Ixodes','Hyalomma','Argas','Alveonasus');n<-nrow(cp);cp$Total<-sample(c(1,2,4,8,15,25,45),n,TRUE);co<-matrix(0,n,8,dimnames=list(NULL,genres));for(i in seq_len(n)){ks<-sample(8,sample(1:3,1,prob=c(.75,.2,.05)));co[i,ks]<-as.vector(rmultinom(1,cp$Total[i],rep(1,length(ks))))};cp<-cbind(cp,co);cp$nonzero_genus<-rowSums(co>0);cp$radius_km<-60*log10(cp$Total+1);stopifnot(all(rowSums(co)==cp$Total))
cc<-st_coordinates(suppressWarnings(st_point_on_surface(projected)));labs<-data.frame(cc,Province=eng);labs<-subset(labs,!Province%in%c('','Hong Kong','Macao','Beijing','Tianjin','Shanghai'));for(i in seq_len(nrow(labs))){k<-labs$Province[i];if(k=='Gansu'){labs$X[i]<-labs$X[i]-100;labs$Y[i]<-labs$Y[i]+90};if(k=='Ningxia'){labs$X[i]<-labs$X[i]+100;labs$Y[i]<-labs$Y[i]-100};if(k=='Taiwan')labs$Y[i]<-labs$Y[i]+180};write.csv(labs,file.path(P,'results/plot_data/china_source_map_labels_20261029.csv'),row.names=FALSE)
vegcols<-c('#C5D4E1','#B4CCDE','#C4D6C0','#E0E0CA','#DCE0BD','#D4DBD8','#BDC8BA','#E6D2BA');names(vegcols)<-zones;gc<-bf_palette('npg-inspired-10',kind='categorical',n=10,skill_root=S)[c(8,2,3,4,1,5,7,10)];names(gc)<-genres
regional_world<-suppressWarnings(st_crop(st_make_valid(st_as_sf(maps::map('world',plot=FALSE,fill=TRUE))),xmin=65,xmax=145,ymin=0,ymax=60))
p<-ggplot()+geom_sf(data=regional_world,fill='white',colour='#AFB4B7',linewidth=.12)+geom_sf(data=projected,fill='white',colour=NA)+geom_sf(data=veg,aes(fill=region_en),colour=NA,alpha=.65)+scale_fill_manual(values=vegcols,name='Ecological fauna',drop=FALSE,labels=function(x)gsub('evergreen broad-leaved','evergreen\nbroad-leaved',gsub('mixed coniferous–broadleaf','mixed coniferous–\nbroadleaf',gsub('deciduous broad-leaved','deciduous\nbroad-leaved',x))),guide=guide_legend(order=1,override.aes=list(alpha=1)))+geom_sf(data=projected,fill=NA,colour='#B5BCBB',linewidth=.14)+new_scale_fill()+geom_scatterpie(data=subset(cp,nonzero_genus>1),aes(X,Y,r=radius_km),cols=genres,colour='#999999',linewidth=.13)+geom_scatterpie(data=subset(cp,nonzero_genus==1),aes(X,Y,r=radius_km),cols=genres,colour=NA)+scale_fill_manual(values=gc,name='Tick genus',drop=FALSE,guide=guide_legend(order=2))+geom_text(data=labs,aes(X,Y,label=Province),family='Arial',size=2.3,colour='#8B9393')+geom_scatterpie_legend(r=60*log10(c(1,6,45)+1),x=-2480,y=-1710,n=3,breaks=60*log10(c(1,6,45)+1),labeller=function(r)round(10^(r/60)-1),size=2.3,family='Arial')+coord_sf(crs=aeqd,default_crs=st_crs(aeqd),xlim=c(-2700,2400),ylim=c(-2100,2400),expand=FALSE)+annotation_north_arrow(location='tl',height=grid::unit(8,'mm'),width=grid::unit(8,'mm'),style=north_arrow_fancy_orienteering(text_size=6.5))+theme_bw(base_family='Arial',base_size=7)+theme(panel.background=element_rect(fill='#D1EEFC'),panel.grid=element_blank(),axis.title=element_blank(),legend.title=element_text(size=7),legend.text=element_text(size=7),legend.key.height=grid::unit(2.8,'mm'),legend.key.width=grid::unit(2.8,'mm'),legend.spacing.y=grid::unit(.4,'mm'),legend.margin=margin(1,1,1,1),plot.margin=margin(2,3,2,2))
inset<-ggplot()+geom_sf(data=china,fill='white',colour='#9CA6AA',linewidth=.15)+coord_sf(xlim=c(105,125),ylim=c(3,24),expand=FALSE)+theme_void()+theme(panel.background=element_rect(fill='#D1EEFC'),panel.border=element_rect(fill=NA,colour='#879197',linewidth=.25),plot.margin=margin(0,0,0,0));p<-p+inset_element(inset,left=.83,bottom=.005,right=.995,top=.235,align_to='panel')
write_plot('SCICASE-091',p,'china_ecological_pies_20261029',cp,list(data_origin='User-authorized synthetic tick-genus counts at160 actual city coordinates; eight source-image traced ecological color regions are approximate and NOT original vegetation shapefile boundaries. Real province geography. No empirical tick distribution or ecological spatial inference.',seed=20261029,crs=aeqd,cities=n,categories=8,ecological_zones=8,count_closure=TRUE,size_mapping='radius=60*log10(Total+1) km',ecology_boundary_origin='Original image pale-color extraction, gap interpolation and geographic clipping; not field/ecological observations.',source_label_caveat='Source image final label Alveonasus read directly from original-size/cropped legend; source spelling retained.'),183,120)
